* { box-sizing: border-box; }
[hidden] { display: none !important; }
:root { color-scheme: dark; font-family: system-ui, sans-serif; font-size: 16px; background: #172b35; color: #f8f0db; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 24px 16px; background: radial-gradient(ellipse at top, #31515a, #172b35 70%); }
.board { width: min(100%, 560px); padding: clamp(24px, 6vw, 44px); text-align: center; background: #203942; border: 3px solid #52716c; border-radius: 18px; box-shadow: 0 12px 0 #101f27, 0 24px 55px #0b171c88; }
.eyebrow, .hand-label { margin: 0; color: #efb85e; font-size: .85rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
h1 { margin: 8px 0; font-size: clamp(2rem, 8vw, 3rem); line-height: 1.1; }
.instructions { margin: 0; color: #c7d5c9; }
.game { margin-top: 28px; padding: 22px 18px; border-radius: 12px; background: #182e36; border: 1px solid #46645f; }
.status { display: flex; align-items: center; justify-content: center; gap: 9px; color: #c7d5c9; }
.status strong { display: inline-grid; place-items: center; min-width: 34px; height: 34px; border-radius: 50%; color: #172b35; background: #efb85e; }
.dice { display: flex; justify-content: center; gap: clamp(6px, 2vw, 12px); margin: 22px 0 25px; }
.die { width: clamp(48px, 14vw, 72px); aspect-ratio: 1; padding: 5px; border: 3px solid #f8f0db; border-radius: 12px; background: #f8f0db; color: #203942; font: 900 clamp(1.8rem, 7vw, 2.8rem)/1 system-ui, sans-serif; cursor: pointer; box-shadow: 0 5px 0 #ad9e7d; transition: transform .12s, background .12s, box-shadow .12s; }
.die:hover { transform: translateY(-3px); }
.die:active { transform: translateY(2px); box-shadow: 0 1px 0 #ad9e7d; }
.die:focus-visible, button:focus-visible { outline: 3px solid #efb85e; outline-offset: 4px; }
.die.held { background: #efb85e; border-color: #efb85e; box-shadow: 0 5px 0 #aa7736; transform: translateY(-4px); }
.die.held::after { content: "HELD"; display: block; margin-top: 5px; font-size: .58rem; line-height: 1; letter-spacing: .08em; }
.hand-label { font-size: .75rem; }
.hand { min-height: 2.2rem; margin: 5px 0 17px; color: #f8f0db; font-size: 1.6rem; font-weight: 850; }
button { min-height: 48px; padding: 11px 20px; border: 0; border-radius: 8px; font: 750 1rem system-ui, sans-serif; cursor: pointer; transition: transform .12s, filter .12s; }
button:hover:not(:disabled) { filter: brightness(1.1); transform: translateY(-2px); }
button:active:not(:disabled) { transform: translateY(2px); }
.roll-button { width: 100%; color: #172b35; background: #efb85e; box-shadow: 0 4px 0 #aa7736; }
.roll-button:disabled { cursor: default; opacity: .5; box-shadow: none; }
.new-button { margin-top: 12px; color: #f8f0db; background: #46645f; }
.hint { min-height: 1.25em; margin: 15px 0 0; color: #b8c9bd; font-size: .9rem; }
footer { margin-top: 22px; color: #b8c9bd; font-size: .9rem; }
@media (max-width: 390px) { .game { padding-inline: 10px; } .die { border-radius: 9px; } }

const diceElement = document.getElementById('dice');
const handElement = document.getElementById('hand');
const rerollsElement = document.getElementById('rerolls');
const rollButton = document.getElementById('roll');
const hintElement = document.getElementById('hint');
let dice = [1, 1, 1, 1, 1];
let held = [false, false, false, false, false];
let rerolls = 2;
let started = false;

function handName(values) {
  const counts = Object.values(values.reduce((map, value) => {
    map[value] = (map[value] || 0) + 1;
    return map;
  }, {})).sort((a, b) => b - a);
  const unique = [...new Set(values)].sort((a, b) => a - b);
  if (counts[0] === 5) return 'Five of a kind';
  if (counts[0] === 4) return 'Four of a kind';
  if (counts[0] === 3 && counts[1] === 2) return 'Full house';
  if (unique.length === 5 && (unique[4] - unique[0] === 4 || unique.join(',') === '1,2,3,4,6')) return 'Straight';
  if (counts[0] === 3) return 'Three of a kind';
  if (counts[0] === 2 && counts[1] === 2) return 'Two pair';
  if (counts[0] === 2) return 'Pair';
  return 'High die';
}

function render() {
  diceElement.replaceChildren();
  dice.forEach((value, index) => {
    const die = document.createElement('button');
    die.type = 'button';
    die.className = `die${held[index] ? ' held' : ''}`;
    die.textContent = String(value);
    die.setAttribute('aria-label', `Die ${index + 1}: ${value}${held[index] ? ', held' : ', not held'}`);
    die.setAttribute('aria-pressed', String(held[index]));
    die.addEventListener('click', () => {
      if (!started || rerolls === 2) return;
      held[index] = !held[index];
      render();
    });
    diceElement.append(die);
  });
  rerollsElement.textContent = String(rerolls);
  rollButton.disabled = rerolls === 0;
}

rollButton.addEventListener('click', () => {
  if (rerolls === 0) return;
  started = true;
  dice = dice.map((value, index) => held[index] ? value : Math.floor(Math.random() * 6) + 1);
  rerolls -= 1;
  handElement.textContent = handName(dice);
  hintElement.textContent = rerolls ? 'Select any dice to hold before your next roll.' : 'Round complete. Start a new round to play again.';
  render();
});

document.getElementById('new-round').addEventListener('click', () => {
  dice = [1, 1, 1, 1, 1];
  held = [false, false, false, false, false];
  rerolls = 2;
  started = false;
  handElement.textContent = 'Ready to roll';
  hintElement.textContent = 'Click or focus a die and press Enter to hold it.';
  render();
});

render();
